'use strict';const $=s=>document.querySelector(s),preferences=KashierPreferences,keys=['density','text','contrast','motion','paper'];
function fill(){const value=preferences.get();for(const key of keys)$('#settings-'+key).value=value[key==='paper'?'receiptPaper':key];}
$('#settings-form').addEventListener('submit',event=>{event.preventDefault();try{const value={};for(const key of keys)value[key==='paper'?'receiptPaper':key]=$('#settings-'+key).value;preferences.set(value);$('#settings-status').textContent='ڕێکخستنەکان لە ئەم وێبگەڕەدا پارێزران.';}catch(error){$('#settings-status').textContent=error.message;}});
$('#settings-reset').addEventListener('click',()=>{try{preferences.reset();fill();$('#settings-status').textContent='ڕێکخستنە بنەڕەتییەکان گەڕانەوە.';}catch(error){$('#settings-status').textContent=error.message;}});preferences.subscribe(fill);fill();
